import { normalizeRegionQuery, oneEditAway } from "./search.ts";

// The world catalog (docs/trip-map/world-spec.md section 3): ISO 3166-1 alpha-2
// IDs, HK/MO/TW merged into CN, plus XK. Generated by scripts/prepare-world-map.mjs.
export type WorldCountry = {
  code: string;
  name: string;
  en: string;
  aliases: string[];
  continent: string;
  /** False for entries with no polygon of their own: reachable from the list only. */
  hasShape: boolean;
  /** [lon, lat] label position. Never a city coordinate. */
  point: [number, number];
};
export type WorldSource = {
  name: string;
  dataset: string;
  version: string;
  commit: string;
  url: string;
  inputSha256: string;
  inputBytes: number;
  license: string;
  licenseUrl: string;
  licenseText: string;
};
export type WorldCatalog = {
  version: string;
  source: WorldSource;
  transform: {
    precisionDecimals: number;
    dropped: { adm0: string; name: string; reason: string }[];
    droppedForCN: string[];
    merged: { adm0: string; name: string; into: string }[];
    droppedPolygons: number;
  };
  china: { file: string; sha256: string };
  geometry: { file: string; sha256: string; bytes: number; features: number };
  continents: Record<string, string>;
  countries: WorldCountry[];
};
export type WorldSearchIndex = Record<string, string[]>;

/** The catalog and its search index are only needed by the world view, so they are
 * split out of the main bundle and fetched on first use. */
export async function loadWorldCatalog(): Promise<{ catalog: WorldCatalog; index: WorldSearchIndex }> {
  const [catalog, index] = await Promise.all([
    import("@kongken/geo-data/world-catalog.json", { with: { type: "json" } }),
    import("@kongken/geo-data/world-search-index.json", { with: { type: "json" } }),
  ]);
  return { catalog: catalog.default as unknown as WorldCatalog, index: index.default as WorldSearchIndex };
}

/** Chinese names, pinyin and initials, English names, aliases and ISO codes all hit
 * ("日本", "riben", "Japan", "JP"). Exact beats prefix beats substring; a one-edit
 * typo is only tried for longer queries when nothing else matches. */
export function searchWorldCountries(
  countries: readonly WorldCountry[],
  index: WorldSearchIndex,
  query: string,
): WorldCountry[] {
  const q = normalizeRegionQuery(query.trim().slice(0, 100));
  if (!q) return [...countries];
  const scored = countries.map((country, order) => {
    const texts = [country.name, country.en, ...country.aliases].map(normalizeRegionQuery);
    const keys = index[country.code] ?? [];
    let score = Infinity;
    if (normalizeRegionQuery(country.code) === q) score = 0;
    else if (texts.includes(q) || keys.includes(q)) score = 1;
    else if (texts.some((t) => t.startsWith(q)) || (q.length >= 2 && keys.some((k) => k.startsWith(q)))) score = 2;
    else if (texts.some((t) => t.includes(q))) score = 3;
    else if (q.length >= 3 && keys.some((k) => k.includes(q))) score = 4;
    return { country, order, score };
  });
  let hits = scored.filter((s) => s.score !== Infinity);
  if (!hits.length && q.length >= 4) {
    hits = scored.filter((s) => {
      const keys = [...texts(s.country), ...(index[s.country.code] ?? [])];
      return keys.some((k) => oneEditAway(q, k));
    });
  }
  return hits.sort((a, b) => a.score - b.score || a.order - b.order).map((s) => s.country);
}

function texts(country: WorldCountry): string[] {
  return [country.name, country.en, ...country.aliases].map(normalizeRegionQuery);
}
